// configschemagen bundles a distribution's config JSON Schema from the
// already-published config.schema.json/yaml file that each of its
// receivers/processors/exporters/connectors/extensions ships in its own Go
// module (generated by that module's own `make check-schemas` upstream). It
// does not invoke schemagen itself: every component is read at the exact
// version pinned by the distribution's manifest.yaml, via the OCB-generated
// build directory's go.mod/go.sum.
package main

import (
	_ "embed"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"

	"go.yaml.in/yaml/v4"
)

//go:embed root-skeleton.json
var rootSkeleton []byte

var categories = []string{"receivers", "processors", "exporters", "connectors", "extensions"}

// originNamespaces lists the repos whose components this tool knows how to
// resolve, in the form used by each repo's own .schemagen.yaml `namespace:`.
var originNamespaces = []string{
	"go.opentelemetry.io/collector",
	"github.com/open-telemetry/opentelemetry-collector-contrib",
}

type manifest struct {
	Dist struct {
		Name string `yaml:"name"`
	} `yaml:"dist"`
	Receivers  []manifestEntry `yaml:"receivers"`
	Processors []manifestEntry `yaml:"processors"`
	Exporters  []manifestEntry `yaml:"exporters"`
	Connectors []manifestEntry `yaml:"connectors"`
	Extensions []manifestEntry `yaml:"extensions"`
}

type manifestEntry struct {
	GoMod string `yaml:"gomod"`
}

func (m *manifest) entries(category string) []manifestEntry {
	switch category {
	case "receivers":
		return m.Receivers
	case "processors":
		return m.Processors
	case "exporters":
		return m.Exporters
	case "connectors":
		return m.Connectors
	case "extensions":
		return m.Extensions
	default:
		return nil
	}
}

func main() {
	manifestFlag := flag.String("manifest", "", "path to the distribution's manifest.yaml")
	buildDirFlag := flag.String("build-dir", "", "the OCB-generated build directory for this distribution (go.mod/go.sum pinned to the release)")
	outFlag := flag.String("o", "", "output path for the bundled config schema")
	flag.Parse()

	if *manifestFlag == "" || *buildDirFlag == "" || *outFlag == "" {
		log.Fatal("usage: configschemagen -manifest <manifest.yaml> -build-dir <ocb build dir> -o <output file>")
	}

	g := &generator{
		buildDir: *buildDirFlag,
		pkgDirs:  map[string]string{},
		schemas:  map[string]map[string]any{},
	}

	if err := g.run(*manifestFlag, *outFlag); err != nil {
		log.Fatal(err)
	}
}

type generator struct {
	buildDir string
	pkgDirs  map[string]string         // import path -> resolved source dir, cached
	schemas  map[string]map[string]any // source dir -> parsed config.schema.*, cached
}

func (g *generator) run(manifestPath, outPath string) error {
	manifestBytes, err := os.ReadFile(manifestPath) // #nosec G304
	if err != nil {
		return err
	}
	var m manifest
	if err := yaml.Unmarshal(manifestBytes, &m); err != nil {
		return fmt.Errorf("parse %s: %w", manifestPath, err)
	}

	var skeleton map[string]any
	if err := json.Unmarshal(rootSkeleton, &skeleton); err != nil {
		return err
	}
	properties, _ := skeleton["properties"].(map[string]any)

	pool := map[string]any{}
	visited := map[string]bool{}
	var failures, unresolved []string

	for _, category := range categories {
		entries := m.entries(category)
		patternProperties := map[string]any{}

		for _, entry := range entries {
			importPath := strings.Fields(entry.GoMod)[0]
			namespace := namespaceFor(importPath)

			compRoot, compType, err := g.bundleComponent(importPath, namespace, pool, visited, &unresolved)
			if err != nil {
				log.Printf("FAILED %s %s: %v", category, importPath, err)
				failures = append(failures, fmt.Sprintf("%s %s: %v", category, importPath, err))
				continue
			}
			log.Printf("bundled %s/%s from %s", category, compType, importPath)

			// The common "key:" (no value) YAML idiom means "use this
			// component with all defaults" -- mapstructure decodes a nil
			// map into a zero-value struct. Accept null alongside object.
			patternProperties[fmt.Sprintf("^%s(/.+)?$", compType)] = map[string]any{
				"anyOf": []any{compRoot, map[string]any{"type": "null"}},
			}
		}

		properties[category] = map[string]any{
			"type":                 "object",
			"patternProperties":    patternProperties,
			"additionalProperties": false,
		}
	}

	skeleton["title"] = m.Dist.Name + " distribution config"
	skeleton["$defs"] = pool

	out, err := json.MarshalIndent(skeleton, "", "  ")
	if err != nil {
		return err
	}
	if err := os.WriteFile(outPath, out, 0o600); err != nil {
		return err
	}

	if len(failures) > 0 {
		log.Printf("%d component(s) had no usable published schema:", len(failures))
		for _, f := range failures {
			log.Printf("  %s", f)
		}
	}
	if len(unresolved) > 0 {
		log.Printf("%d ref(s) could not be resolved (left as generic object):", len(unresolved))
		for _, u := range unresolved {
			log.Printf("  %s", u)
		}
	}
	log.Printf("wrote %s ($defs pool: %d entries)", outPath, len(pool))
	return nil
}

// bundleComponent resolves a single component's own published schema and
// rewrites every $ref it contains to point into the shared pool.
func (g *generator) bundleComponent(importPath, namespace string, pool map[string]any, visited map[string]bool, unresolved *[]string) (map[string]any, string, error) {
	srcDir, err := g.goListDir(importPath)
	if err != nil {
		return nil, "", err
	}
	compType, ok := readComponentType(srcDir)
	if !ok {
		return nil, "", fmt.Errorf("no metadata.yaml / type")
	}
	schema, ok := g.loadPublishedSchema(srcDir)
	if !ok {
		return nil, "", fmt.Errorf("no published config.schema.json/yaml in module")
	}

	compRoot := map[string]any{}
	for k, v := range schema {
		if k != "$defs" {
			compRoot[k] = v
		}
	}
	g.resolveRefs(compRoot, importPath, namespace, pool, visited, unresolved)
	return compRoot, compType, nil
}

func namespaceFor(importPath string) string {
	for _, ns := range originNamespaces {
		if strings.HasPrefix(importPath, ns) {
			return ns
		}
	}
	return ""
}

func (g *generator) goListDir(importPath string) (string, error) {
	if dir, ok := g.pkgDirs[importPath]; ok {
		if dir == "" {
			return "", fmt.Errorf("go list failed")
		}
		return dir, nil
	}
	cmd := exec.Command("go", "list", "-f", "{{.Dir}}", importPath) //nolint:gosec // import paths come from manifest.yaml / schemagen refs, not user input
	cmd.Dir = g.buildDir
	dirOut, runErr := cmd.Output()
	if runErr != nil {
		g.pkgDirs[importPath] = ""
		return "", fmt.Errorf("go list failed")
	}
	dir := strings.TrimSpace(string(dirOut))
	g.pkgDirs[importPath] = dir
	return dir, nil
}

func readComponentType(srcDir string) (string, bool) {
	data, err := os.ReadFile(filepath.Join(srcDir, "metadata.yaml")) // #nosec G304
	if err != nil {
		return "", false
	}
	var md struct {
		Type string `yaml:"type"`
	}
	if err := yaml.Unmarshal(data, &md); err != nil || md.Type == "" {
		return "", false
	}
	return md.Type, true
}

func (g *generator) loadPublishedSchema(srcDir string) (map[string]any, bool) {
	if schema, ok := g.schemas[srcDir]; ok {
		return schema, schema != nil
	}
	for _, candidate := range []struct {
		name   string
		unjson bool
	}{
		{"config.schema.json", true},
		{"config.schema.yaml", false},
	} {
		data, err := os.ReadFile(filepath.Join(srcDir, candidate.name)) // #nosec G304
		if err != nil {
			continue
		}
		var schema map[string]any
		if candidate.unjson {
			err = json.Unmarshal(data, &schema)
		} else {
			err = yaml.Unmarshal(data, &schema)
		}
		if err == nil {
			g.schemas[srcDir] = schema
			return schema, true
		}
	}
	g.schemas[srcDir] = nil
	return nil, false
}

var relPrefix = regexp.MustCompile(`^\.\.?/`)

// parsedRef describes an external $ref. form is one of "relative"
// (relative to the current package's own import path), "absolute"
// (relative to the current origin's repo root, i.e. its .schemagen.yaml
// `namespace:`), or "qualified" (a full Go import path already).
type parsedRef struct {
	pathPart string
	defName  string
	form     string
}

// parseRef returns nil for a bare local name (same-file $defs).
func parseRef(ref string) *parsedRef {
	if !strings.Contains(ref, "/") {
		return nil
	}
	var body, form string
	switch {
	case relPrefix.MatchString(ref):
		body, form = ref, "relative"
	case strings.HasPrefix(ref, "/"):
		body, form = strings.TrimPrefix(ref, "/"), "absolute"
	default:
		body, form = ref, "qualified"
	}
	idx := strings.LastIndex(body, ".")
	if idx < 0 {
		return &parsedRef{pathPart: body, defName: "", form: form}
	}
	return &parsedRef{pathPart: body[:idx], defName: body[idx+1:], form: form}
}

// resolveRefs recursively rewrites every $ref under element to point into
// pool under "#/$defs/<key>", pulling the referenced def in from the same
// published file (bare names) or another package's published file
// (relative/absolute/qualified refs).
func (g *generator) resolveRefs(element any, currentImportPath, currentNamespace string, pool map[string]any, visited map[string]bool, unresolved *[]string) {
	switch e := element.(type) {
	case map[string]any:
		if refAny, ok := e["$ref"]; ok {
			ref, _ := refAny.(string)
			var targetImportPath, defName, targetNamespace string

			if parsed := parseRef(ref); parsed == nil {
				targetImportPath, defName, targetNamespace = currentImportPath, ref, currentNamespace
			} else {
				switch parsed.form {
				case "relative":
					suffix := strings.TrimPrefix(strings.TrimPrefix(parsed.pathPart, "./"), "../")
					targetImportPath = strings.TrimSuffix(currentImportPath, "/") + "/" + suffix
				case "absolute":
					targetImportPath = strings.TrimSuffix(currentNamespace, "/") + "/" + parsed.pathPart
				default: // qualified
					targetImportPath = parsed.pathPart
				}
				defName = parsed.defName
				targetNamespace = namespaceFor(targetImportPath)
				if targetNamespace == "" {
					targetNamespace = currentNamespace
				}
			}

			key := strings.NewReplacer("/", "_", ".", "_").Replace(targetImportPath) + "__" + defName
			e["$ref"] = "#/$defs/" + key

			if _, inPool := pool[key]; !inPool && !visited[key] {
				visited[key] = true
				targetDef, ok := g.lookupDef(targetImportPath, defName)
				if !ok {
					*unresolved = append(*unresolved, fmt.Sprintf("%s -> %s (as %s.%s)", currentImportPath, ref, targetImportPath, defName))
					delete(e, "$ref")
					e["type"] = "object"
				} else {
					g.resolveRefs(targetDef, targetImportPath, targetNamespace, pool, visited, unresolved)
					pool[key] = targetDef
				}
			}
		}
		for k, v := range e {
			if k != "$ref" {
				g.resolveRefs(v, currentImportPath, currentNamespace, pool, visited, unresolved)
			}
		}
	case []any:
		for _, item := range e {
			g.resolveRefs(item, currentImportPath, currentNamespace, pool, visited, unresolved)
		}
	}
}

func (g *generator) lookupDef(importPath, defName string) (map[string]any, bool) {
	srcDir, err := g.goListDir(importPath)
	if err != nil {
		return nil, false
	}
	schema, ok := g.loadPublishedSchema(srcDir)
	if !ok {
		return nil, false
	}
	defs, _ := schema["$defs"].(map[string]any)
	def, ok := defs[defName].(map[string]any)
	if !ok {
		return nil, false
	}
	// Deep copy so mutations for this reference site don't leak into other
	// sites that resolve the same def.
	raw, err := json.Marshal(def)
	if err != nil {
		return nil, false
	}
	var cloned map[string]any
	if err := json.Unmarshal(raw, &cloned); err != nil {
		return nil, false
	}
	return cloned, true
}
